query:
PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?result WHERE {
  prodi:employee-brant pv:worksIn ?department .
  ?department a pv:Department ;
    rdfs:label ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?expert pv:hasExpertise pv:Transistors ;
           rdfs:label ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?result WHERE {
  prodi:sensor-switch-m558-2275045 pv:responsibleFor ?department .
  ?department a pv:Department ;
    rdfs:label ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT (COUNT(DISTINCT ?sensorSwitch) AS ?result) WHERE {
  ?sensorSwitch a pv:SensorSwitch .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?expert a pv:NetworkExpert ;
           pv:worksIn prodi:MarketingDepartment ;
           rdfs:name ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?result (MAX(?price) AS ?maxPrice) WHERE {
  ?service a pv:Service ; pv:hasPrice ?price .
} ORDER BY DESC(?maxPrice) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?result a pv:Coil ;
           pv:baseArea "[15,15]"^^xsd:string ;
           pv:weight ?weight .
} ORDER BY DESC(?weight) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?result a pv:Pontiometer ;
           pv:volume ?volume .
} ORDER BY ASC(?volume) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?result (MAX(?density) AS ?maxDensity) WHERE {
  ?coil a pv:Coil ; pv:density ?density .
} GROUP BY ?coil ORDER BY DESC(?maxDensity) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?name ?email ?phone WHERE {
  ?person a pv:StaffMember ;
           pv:name ?name ;
           pv:email ?email ;
           pv:phone ?phone .
  FILTER NOT EXISTS {
    ?manager pv:manages ?person .
  }
} ORDER BY ?name

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

ASK {
  ?department a pv:Department ;
               NOT EXISTS { ?department pv:hasManager ?manager } .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?supplierName ?addressDetails WHERE {
  ?supplier a pv:Supplier ;
             rdfs:label ?supplierName ;
             pv:hasAddress ?address .
  ?address rdfs:label ?addressDetails .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?result (COUNT(?product) AS ?products) WHERE {
  ?product a pv:Product ; pv:hasSkill ?skill .
} GROUP BY ?skill ORDER BY DESC(?products) LIMIT 3

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?bom (COUNT(?part) AS ?partCount) (SUM(?quantity) AS ?totalQuantity) WHERE {
  ?bom a pv:BillOfMaterial ;
       pv:containsPart ?part ;
       pv:hasTotalQuantity ?quantity .
} GROUP BY ?bom HAVING (?totalQuantity > 600) ORDER BY DESC(?totalQuantity)

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result ?width ?height ?depth WHERE {
  ?result a pv:Hardware ;
           pv:width ?width ;
           pv:height ?height ;
           pv:depth ?depth .
  FILTER(?width > ?height && ?depth < 50)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?id ?name WHERE {
  ?item a pv:HardwareItem ;
         prodi:id ?id ;
         rdfs:name ?name .
  FILTER NOT EXISTS {
    ?item pv:hasActiveProductManager ?manager .
  }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?manager (COUNT(?employee) AS ?teamSize) WHERE {
  ?manager a pv:Manager ;
            pv:manages ?department .
  ?employee a pv:Employee ;
             pv:worksIn ?department .
} GROUP BY ?manager

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result ?id ?name ?width WHERE {
  ?result a pv:HardwareItem ;
           pv:id ?id ;
           pv:name ?name ;
           pv:width ?width .
  FILTER(?width >= (SELECT AVG(?width) FROM { ?item a pv:HardwareItem ; pv:width ?width . }))
} ORDER BY DESC(?width) LIMIT 10

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  prodi:BOMPart prodi:deliveredTo prodi:SkySyncMechWave ;
    pv:originCountry ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
SELECT ?result (COUNT(?product) AS ?count) WHERE {
  ?product a pv:Product ; pv:managedBy ?result .
} GROUP BY ?result ORDER BY DESC(?count) LIMIT 1
